using System.Reflection;
using System.Text.Json;
using PKHeX.Core;
var type=Assembly.Load("PKHeXBridge").GetType("EditorSession")!;
var saveField=type.GetField("save",BindingFlags.Instance|BindingFlags.NonPublic)!;
var entityField=type.GetField("entity",BindingFlags.Instance|BindingFlags.NonPublic)!;
int checks=0;string scratch=Path.Combine(Path.GetTempPath(),"keepsake023-"+Guid.NewGuid());Directory.CreateDirectory(scratch);
object Session(SaveFile save){var s=Activator.CreateInstance(type,new object[]{null!})!;saveField.SetValue(s,save);return s;}
SaveFile Current(object s)=>(SaveFile)saveField.GetValue(s)!;
JsonElement Req(object s,object r){using var doc=JsonDocument.Parse(JsonSerializer.Serialize(r));checks++;try{return JsonSerializer.SerializeToElement(type.GetMethod("Handle")!.Invoke(s,new object[]{doc.RootElement})!);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException!).Throw();throw;}}
int Rev(object s)=>Req(s,new{op="state"}).GetProperty("revision").GetInt32();
void Edit(object s,string kind,string id,params (string field,string value)[] values)=>Req(s,new{op="extraSet",kind,id,revision=Rev(s),edits=values.Select(v=>new{v.field,v.value})});
void Act(object s,string kind,string id,string mode)=>Req(s,new{op="extraSet",kind,id,mode,revision=Rev(s)});
JsonElement Row(object s,string kind,string id)=>Req(s,new{op="extraEntry",kind,id});
string Value(object s,string kind,string id,string field)=>Row(s,kind,id).GetProperty("fields").EnumerateArray().Single(f=>f.GetProperty("id").GetString()==field).GetProperty("value").GetString()!;
void Assert(bool pass,string why){checks++;if(!pass)throw new Exception(why);}
void Reject(Action call,string why){try{call();}catch{checks++;return;}throw new Exception("Expected rejection: "+why);}
string Export(object s,string kind,string id,bool decrypted=false){string file=Path.Combine(scratch,Guid.NewGuid()+".bin");Req(s,new{op="extraExport",kind,id,path=file,decrypted});return file;}
void Import(object s,string kind,string id,string path)=>Req(s,new{op="extraSet",kind,id,mode="import",path,revision=Rev(s)});
void Roundtrip(object s,Func<byte[],SaveFile> parse,string kind,string id){var expected=Row(s,kind,id).ToString();var copy=parse(Current(s).Write().ToArray());Assert(copy.ChecksumsValid,kind+" checksums");saveField.SetValue(s,copy);Assert(Row(s,kind,id).ToString()==expected,kind+" serialized fields");}
foreach(var game in new[]{GameVersion.X,GameVersion.Y,GameVersion.OR,GameVersion.AS}){
 var s=Session(BlankSaveFile.Get(game,"Fixture"));var sav=(ISaveBlock6Main)Current(s);var before=Current(s).Data.ToArray();Assert(Req(s,new{op="extraPage",kind="link6"}).GetProperty("entries").GetArrayLength()==13,"Link rewards");Assert(before.SequenceEqual(Current(s).Data.ToArray()),"Link read purity");
 Edit(s,"link6","settings",("Origin","KeepSake delivery"),("Enabled","true"),("BattlePoints","9999"),("Pokemiles","321"));for(int i=1;i<=6;i++)Edit(s,"link6","item:"+i,("Item"+i,"1"),("Quantity"+i,"65535"));Assert(((ISaveBlock6Main)Current(s)).Link.Gifts.Quantity6==65535,"Link final item");string file=Export(s,"link6","settings");Assert(new FileInfo(file).Length==PL6.Size,"Link file size");Edit(s,"link6","settings",("Origin","Changed"));Import(s,"link6","settings",file);Assert(Value(s,"link6","settings","Origin")=="KeepSake delivery","Link import");Req(s,new{op="undo"});Assert(Value(s,"link6","settings","Origin")=="Changed","Link Undo");Req(s,new{op="redo"});Reject(()=>Edit(s,"link6","item:1",("Quantity1","65536")),"Link limit");
 Roundtrip(s,b=>game is GameVersion.X or GameVersion.Y?new SAV6XY(b):new SAV6AO(b),"link6","settings");var link=((ISaveBlock6Main)Current(s)).Link;Assert(link.Checksum==Checksums.CRC16_CCITT(link.Data[0x200..^4]),"Inner link checksum");Console.WriteLine("PASS "+game+" Pokémon Link");
}
