 // Exercise the exact tile limit with deterministic, distinct two-color patterns.
 var random=new Random(23);var tiles=Enumerable.Range(0,256).Select(_=>Enumerable.Range(0,64).Select(_=>(byte)random.Next(2)).ToArray()).ToArray();
 byte[] TileImage(int unique){var image=new byte[256*192*4];for(int n=0;n<768;n++)for(int y=0;y<8;y++)for(int x=0;x<8;x++){int i=(((n/32)*8+y)*256+(n%32)*8+x)*4;byte c=(byte)(tiles[n%unique][y*8+x]*255);image[i]=image[i+1]=image[i+2]=c;image[i+3]=255;}return image;}
