 Roundtrip(s,b=>game is GameVersion.B or GameVersion.W?new SAV5BW(b):new SAV5B2W2(b),"globallink5","settings");Assert(((SAV5)Current(s)).CGearSkinData.Span.SequenceEqual(skinBefore),"Serialized skin");File.WriteAllBytes(Path.Combine(scratch,game+"-fixture.sav"),Current(s).Write().ToArray());Console.WriteLine("PASS "+game+" Global Link / downloaded content / C-Gear");
