foreach(var game in new[]{GameVersion.Pt,GameVersion.HG,GameVersion.SS}){
 SAV4 sav=game==GameVersion.Pt?new SAV4Pt(new byte[0x80000]):new SAV4HGSS(new byte[0x80000]);
