 foreach(var block in blocks.Skip(2)){var video=new BattleVideo4(sav.Buffer.Slice(block.Offset,BattleVideo4.SIZE_USED)){IsDecrypted=true,Key=0,Magic=0x20060623,Revision=7,BlockSize=BattleVideo4.SIZE_USED-16,BlockID=(ushort)block.ID};video.RefreshChecksums();video.Encrypt();}
 var s=Session(sav);var before=sav.Data.ToArray();for(int i=0;i<4;i++){Row(s,"dlc4","video:"+i);Assert(Current(s).Data.SequenceEqual(before),"Video preview purity");string path=Export(s,"dlc4","video:"+i,true);var file=new BattleVideo4(File.ReadAllBytes(path)){IsDecrypted=true,Key=123456};file.RefreshChecksums();var data=file.Data.ToArray();File.WriteAllBytes(path,data);Import(s,"dlc4","video:"+i,path);var current=((SAV4)Current(s)).GetBattleVideo(i);Assert(current!=null&&current.Key==0&&current.Revision==7&&current.ChecksumValid,"Video metadata / key preservation");Req(s,new{op="undo"});Assert(Current(s).Data.SequenceEqual(before),"Video import Undo");}
 Roundtrip(s,b=>game==GameVersion.Pt?new SAV4Pt(b):new SAV4HGSS(b),"dlc4","video:0");Console.WriteLine("PASS "+game+" encrypted/decrypted battle videos");
}
